use super::*;
use model::{TableCell, TableRow};
fn table()->Table{Table{id:NodeId::new(),properties:Default::default(),rows:(0..2).map(|y|TableRow{id:NodeId::new(),repeat_as_header:y==0,allow_break_across_pages:true,height_mm:None,cells:(0..2).map(|x|TableCell{id:NodeId::new(),blocks:(vec![Block::Paragraph(Paragraph::plain(format!("{y}:{x}")))]).into(),column_span:1,row_span:1,width_mm:Some(30.0),shading:None,borders:None,vertical_alignment:Default::default()}).collect()}).collect()}}
#[test]fn rectangle_copy_paste_and_undo(){let t=table();let id=t.id.clone();let ids=t.rows.iter().flat_map(|r|r.cells.iter().map(|c|c.id.clone())).collect::<Vec<_>>();let mut d=Document::default();let p=Paragraph::plain("AB");let pid=p.id.clone();d.sections[0].blocks=(vec![Block::Paragraph(p),Block::Table(t)]).into();let mut e=EditorState::new(d);let f=e.copy_table_cells(&id,&ids).unwrap();assert_eq!(f.plain_text,"0:0\t0:1\n1:0\t1:1");let before=e.document.clone();e.set_caret(pid,1);e.paste_fragment(&f).unwrap();assert_eq!(e.document.sections[0].blocks.iter().filter(|b|matches!(b,Block::Table(_))).count(),2);assert!(e.undo());assert_eq!(e.document,before);}
